SELECT /* LGVPAY00031.retrievePaidLeaveEmpList */ tpp.payment_yyyymm AS pay_month , em.employee_number AS employee_no , em.full_name_english AS employee_name , em.full_name_local AS employee_name_local , em.organization_id , um.default_org_id , em.org_name_local AS organization_name , em.person_type , em.assignment_category AS employment_category_code , em.status , em.grade AS grade_code , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') as date_hire_subsidiary , TO_CHAR(em.date_retire, 'DD/MM/YYYY') as date_retire , (SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS grade_title , em.grade_type AS emp_category_name , em.attribute10 AS shift_type_code ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name , em.supervisor , (select ema.full_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_name , (select ema.org_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_org_name , (select om.parent_org_name from org_master om where om.organization_id = em.organization_id) as section , um.employee_mobile_phone_no as mobile_phone , tpp.paid_leave_id as paid_leave_id , TO_CHAR(tpp.start_date, 'DD/MM/YYYY') as start_date , TO_CHAR(tpp.end_date, 'DD/MM/YYYY') as end_date , tpp.paid_leave_detail_code as paid_leave_detail_code , tpp.note as note , tpp.base_salary as base_salary , tpp.position_allowance as position_allowance , tpp.qualification_allowance as qualification_allowance , tpp.job_allowance as job_allowance , tpp.adjustment_allowance_1 as adjustment_allowance_1 , tpp.adjustment_allowance_2 as adjustment_allowance_2 , tpp.adjustment_allowance_3 as adjustment_allowance_3 , tpp.base_salary_cal as base_salary_cal FROM tb_pay_paid_leave_n tpp , emp_master em , lgcom_user_m um , lgcom_company_v cv WHERE em.employee_number = tpp.employee_no AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code AND tpp.payment_yyyymm = #{payMonth} AND tpp.paid_leave_detail_code = #{paidLeaveDetailCode}
AND tpp.employee_no = #{employeeNo}
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
AND tpp.paid_leave_id = #{paidLeaveId}
AND tpp.payment_yyyymm = #{payMonth}
ORDER BY em.employee_number asc

