        UPDATE /*LGVPAY00031.updatePaidLeaveEmp*/
               tb_pay_paid_leave_n 
		SET  employee_no    =  #{employeeNo}
             ,start_date    =  #{startDate}
             ,end_date    =  #{endDate}
             ,base_salary    =  #{baseSalary}
             ,position_allowance    =  #{positionAllowance}
             ,qualification_allowance    =  #{qualificationAllowance}
             ,job_allowance    =  #{jobAllowance}
             ,adjustment_allowance_1    =  #{adjustmentAllowance1}
             ,adjustment_allowance_2    =  #{adjustmentAllowance2}
             ,adjustment_allowance_3    =  #{adjustmentAllowance3}
             ,base_salary_cal    =  #{baseSalaryCal}
             ,note    =  #{note}
             , last_update_user_id             = #{applicationUserId}            							/* 최종수정사용자아이디 */
             , last_update_date                = sysdate                 							/* 최종수정일자 */
        WHERE  paid_leave_id   = #{paidLeaveId}

MERGE INTO /*LGVPAY00031.saveCalculatePLDetail*/ TB_PAY_PAID_LEAVE_DETAIL_N T USING ( WITH Target_Emps AS ( SELECT employee_no, start_date, end_date FROM tb_pay_paid_leave_n WHERE payment_yyyymm = #{payMonth} AND paid_leave_detail_code = #{paidLeaveDetailCode}
),
Leave_Stats AS ( SELECT r.EMPLOYEE_NO, COUNT(DISTINCT r.TIME_AND_ATTENDANCE_DATE) AS PAID_LEAVE_DAYS, SUM(bb.work_hours) AS PAID_LEAVE_HOURS FROM Tb_Att_Result_n r JOIN tb_att_base_bas_n bb ON r.shift_type_code = bb.shift_type_code AND r.time_and_attendance_date = bb.time_and_attendance_date JOIN Target_Emps te ON r.EMPLOYEE_NO = te.employee_no AND r.time_and_attendance_date BETWEEN te.start_date AND te.end_date WHERE r.TIME_AND_ATTENDANCE_YYYYMM = #{payMonth} AND r.TIME_AND_ATTENDANCE_CODE = 'PL' AND r.TIME_ATTEND_DETAIL_CODE = #{paidLeaveDetailCode} GROUP BY r.EMPLOYEE_NO ),
Work_Stats AS ( SELECT r.employee_no, SUM(DECODE(b.time_and_attendance_code, 'NW', 1, 'PH', 1, 0)) AS perfect_work_days, SUM(lgvpay_info_pkg.get_work_hours('LGDVN', r.employee_no, b.time_and_attendance_date, DECODE(r.time_and_attendance_code, 'WH', 'WH', 'PH', 'PH', 'NW'), b.shift_type_code, b.work_hours, 'pay_perfect_hours')) AS perfect_work_hours, SUM(CASE WHEN (c.paid_days > 0 OR c.attendance_days > 0) THEN lgvpay_info_pkg.get_work_hours('LGDVN', r.employee_no, b.time_and_attendance_date, DECODE(r.time_and_attendance_code, 'WH', 'WH', 'PH', 'PH', 'NW'), b.shift_type_code, b.work_hours, 'pay_perfect_hours') END) AS actual_hours, (SUM(CASE WHEN (c.paid_days > 0 OR c.attendance_days > 0) THEN lgvpay_info_pkg.get_work_hours('LGDVN', r.employee_no, b.time_and_attendance_date, DECODE(r.time_and_attendance_code, 'WH', 'WH', 'PH', 'PH', 'NW'), b.shift_type_code, b.work_hours, 'pay_perfect_hours') WHEN r.time_and_attendance_code = 'WH' THEN 0 ELSE (SELECT ar.work_hours FROM tb_att_result_n ar WHERE ar.employee_no = r.employee_no AND ar.time_and_attendance_date = b.time_and_attendance_date AND ar.time_and_attendance_code != 'NN') END) - 192 - NVL(SUM(NVL(r.tardy_hours, 0)) + SUM(NVL(r.going_out_hours, 0)) + SUM(NVL(r.early_leave_hours, 0)), 0)) AS extra_hours FROM tb_att_result_n r JOIN tb_att_code_c c ON r.time_and_attendance_code = c.time_and_attendance_code JOIN tb_att_base_bas_n b ON r.shift_type_code = b.shift_type_code AND r.time_and_attendance_date = b.time_and_attendance_date JOIN emp_master em ON em.employee_number = r.employee_no JOIN Target_Emps te ON r.employee_no = te.employee_no WHERE r.time_and_attendance_yyyymm = #{payMonth} GROUP BY r.employee_no ) SELECT te.employee_no, NVL(l.PAID_LEAVE_DAYS, 0) as PAID_LEAVE_DAYS, NVL(l.PAID_LEAVE_HOURS, 0) as PAID_LEAVE_HOURS, w.perfect_work_days, w.perfect_work_hours, w.actual_hours, w.extra_hours, nvl(lgvpay_info_pkg.get_base_pay(te.employee_no, TO_CHAR(LAST_DAY(TO_DATE(#{payMonth}, 'YYYYMM')), 'YYYYMMDD'),'LGDVN', 'A'),0) as BASE_SALARY, nvl(lgvpay_info_pkg.get_qualification_allowance(te.employee_no, TO_CHAR(LAST_DAY(TO_DATE(#{payMonth}, 'YYYYMM')), 'YYYYMMDD'),'LGDVN'),0) as QUALIFICATION_ALLOWANCE, nvl(lgvpay_info_pkg.get_encour_allowance(te.employee_no, TO_CHAR(LAST_DAY(TO_DATE(#{payMonth}, 'YYYYMM')), 'YYYYMMDD')),0) as ENCOURAGEMENT_INCENTIVE_BASE, nvl(lgvpay_common_pkg.get_calc_var_value( 'LGDVN','ATTENDANCE_INCENTIVE', TO_CHAR(LAST_DAY(TO_DATE(#{payMonth}, 'YYYYMM')), 'YYYYMMDD')),0)as ATTENDANCE_INCENTIVE_BASE FROM Target_Emps te LEFT JOIN Leave_Stats l ON te.employee_no = l.EMPLOYEE_NO LEFT JOIN Work_Stats w ON te.employee_no = w.employee_no ) S ON ( T.payment_yyyymm = #{payMonth} AND T.paid_leave_detail_code = 'PL_PLP' AND T.employee_no = S.employee_no ) WHEN MATCHED THEN UPDATE SET T.paid_leave_days = S.PAID_LEAVE_DAYS, T.paid_leave_hours = S.PAID_LEAVE_HOURS, T.perfect_work_days = S.perfect_work_days, T.perfect_work_hours = S.perfect_work_hours, T.actual_hours = S.actual_hours, T.extra_hours = S.extra_hours, T.BASE_SALARY = S.BASE_SALARY, T.QUALIFICATION_ALLOWANCE = S.QUALIFICATION_ALLOWANCE, T.ENCOURAGEMENT_INCENTIVE_BASE = S.ENCOURAGEMENT_INCENTIVE_BASE, T.ATTENDANCE_INCENTIVE_BASE = S.ATTENDANCE_INCENTIVE_BASE, T.last_update_date = SYSDATE, T.last_update_user_id = -1
WHEN NOT MATCHED THEN INSERT ( payment_yyyymm, paid_leave_detail_code, employee_no, paid_leave_days, paid_leave_hours, perfect_work_days, perfect_work_hours, actual_hours, extra_hours, BASE_SALARY, QUALIFICATION_ALLOWANCE, ENCOURAGEMENT_INCENTIVE_BASE, ATTENDANCE_INCENTIVE_BASE, creation_date, creation_user_id ) VALUES ( #{payMonth}, #{paidLeaveDetailCode}, S.EMPLOYEE_NO, S.PAID_LEAVE_DAYS, S.PAID_LEAVE_HOURS, S.perfect_work_days, S.perfect_work_hours, S.actual_hours, S.extra_hours, S.BASE_SALARY, S.QUALIFICATION_ALLOWANCE, S.ENCOURAGEMENT_INCENTIVE_BASE, S.ATTENDANCE_INCENTIVE_BASE, SYSDATE, #{applicationUserId} )

