INSERT INTO /* LGVPAY00031.createExcelDownloadData */ XXLGE_EXPORT_INFO (SESSION_ID, CREATED_BY, CREATION_DATE, SEQ_NO, CHARACTER_SET_NAME , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8 , ATTRIBUTE9, ATTRIBUTE10 , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15 , ATTRIBUTE16, ATTRIBUTE17, ATTRIBUTE18, ATTRIBUTE19, ATTRIBUTE20, ATTRIBUTE21, ATTRIBUTE22, ATTRIBUTE23 , ATTRIBUTE24, ATTRIBUTE25, ATTRIBUTE26, ATTRIBUTE27, ATTRIBUTE28, ATTRIBUTE29) SELECT AA.* FROM ( SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 1 AS ORDER_BY , 'KO16KSC5601' , 'Employee No' AS EMPLOYEE_NO , 'Employee Name' AS EMPLOYEE_NAME_LOCAL , 'Employee Eng Name' AS EMPLOYEE_NAME , 'PaymentYyyymm' AS payment_yyyymm , 'Start Date' AS start_date , 'End Date' AS end_date , 'Paid Leave Detail Code' AS paid_leave_detail_code , 'Base Salary' AS base_salary , 'Position Allowance' AS position_allowance , 'Qualification Allowance' AS qualification_allowance , 'Job Allowance' AS job_allowance , 'Adjustment Allowance 1' AS adjustment_allowance_1 , 'Adjustment Allowance 2' AS adjustment_allowance_2 , 'Adjustment Allowance 3' AS adjustment_allowance_3 , 'Base Salary Calculation' AS base_salary_cal , 'Note' AS note , 'Organization Name' AS ORGANIZATION_NAME , 'Type' AS PERSON_TYPE , 'Status' AS STATUS , 'Grade' AS GRADE_CODE , 'Title' AS GRADE_TITLE , 'Emp. Category' AS EMP_CATEGORY_NAME , 'Hire Date' AS DATE_HIRE_SUBSIDIARY , 'Resignation Date' AS DATE_RETIRE , 'Supervisor' AS SUPERVISOR , 'Supervisor' AS SUPERVISOR_NAME , 'Supervisor' AS SUPERVISOR_ORG_NAME , 'Mobile Phone No.' AS MOBILE_PHONE , 'Work Type' AS SHIFT_TYPE_NAME FROM DUAL UNION ALL SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 2 AS ORDER_BY , 'KO16KSC5601' , em.employee_number AS employee_no , em.full_name_english AS employee_name , em.full_name_local AS employee_name_local , tpp.payment_yyyymm AS pay_month , TO_CHAR(tpp.start_date, 'DD/MM/YYYY') as start_date , TO_CHAR(tpp.end_date, 'DD/MM/YYYY') as end_date , tpp.paid_leave_detail_code as paid_leave_detail_code , TO_CHAR(tpp.base_salary) as base_salary , TO_CHAR(tpp.position_allowance) as position_allowance , TO_CHAR(tpp.qualification_allowance) as qualification_allowance , TO_CHAR(tpp.job_allowance) as job_allowance , TO_CHAR(tpp.adjustment_allowance_1) as adjustment_allowance_1 , TO_CHAR(tpp.adjustment_allowance_2) as adjustment_allowance_2 , TO_CHAR(tpp.adjustment_allowance_3) as adjustment_allowance_3 , TO_CHAR(tpp.base_salary_cal) as base_salary_cal , tpp.note as note , em.org_name_local AS organization_name , em.person_type AS person_type , em.status AS status , em.grade AS grade_code , (SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS grade_title , em.grade_type AS emp_category_name , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') AS date_hire_subsidiary , TO_CHAR(em.date_retire, 'DD/MM/YYYY') AS date_retire , em.supervisor AS supervisor , (select ema.full_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_name , (select ema.org_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_org_name , um.employee_mobile_phone_no as mobile_phone ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name FROM tb_pay_paid_leave_n tpp , emp_master em , lgcom_user_m um , lgcom_company_v cv WHERE em.employee_number = tpp.employee_no AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code AND tpp.payment_yyyymm = #{payMonth}
AND tpp.employee_no = #{employeeNo}
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
ORDER BY ORDER_BY, EMPLOYEE_NO asc ) AA ORDER BY ORDER_BY, AA.EMPLOYEE_NO asc
